// FUNC_AT(0x000b9770)
bool SRuleDamage::CheckRule() {
    if (target.type == kTargetStats)
        return Ftol(Stats()->maxDamage) > threshold;
    int health = TargetHealth(target);
    int damage = lastHealth - health;
    lastHealth = health;
    return damage > threshold;
}

