// FUNC_AT(0x000b9eb0)
bool SRuleHealth::CheckRule() {
    int value;
    if (target.type == kTargetStats) {
        AIElementStats *stats = Stats();
        value = Ftol(health.direction != 0 ? stats->maxHitPoints : stats->minHitPoints);
    } else {
        value = TargetHealth(target);
    }
    return health.Crossed(value);
}

